import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // 정수 하나를 받아 조건의 참·거짓을 돌려주는 규칙이에요.
        Predicate<Integer> enough = price -> price >= 2000;
        System.out.println(enough.test(1000));
        System.out.println(enough.test(2000));
    }
}

