import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> prices = List.of(1000, 2000, 3000);
        // 아래 출력은 실행 시점만 관찰하기 위한 임시 도구예요.
        Stream<Integer> selected = prices.stream().filter(price -> {
            System.out.println("check");
            return price >= 2000;
        });
        System.out.println("ready");
        System.out.println(selected.toList());
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> prices = List.of(1000, 2000, 3000);
        Stream<Integer> selected = prices.stream().filter(price -> price >= 2000);
        System.out.println(selected.toList());
        // 앞에서 소비한 같은 스트림을 다시 쓰려 해요.
