import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> prices = List.of(1000, 2000, 3000);
        // 결과가 없을 수 있어 Optional로 받아요.
        Optional<Integer> first = prices.stream().filter(price -> price >= 5000).findFirst();
        System.out.println(first.isPresent());
        System.out.println(first.orElse(0));
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> prices = List.of(3000, 1000, 3000);
        // 중복을 없앤 새 결과만 정렬해요.
        System.out.println(prices.stream().distinct().sorted().toList());
        System.out.println(prices);
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> items = List.of("book", "pen", "book");
        // 같은 키를 만났을 때 사용할 병합 규칙을 확인해요.
        Map<String, Integer> counts = items.stream().collect(Collectors.toMap(item -> item, item -> 1));
        System.out.println(new TreeMap<>(counts));
    }
}

