tasks.solution:
import java.util.*;
import java.util.function.*;
import java.util.stream.*;


public class Main {
    public static void main(String[] args) {
        // 작은 정수 가격과 기준을 같은 처리 흐름으로 검사하세요.
        int[] prices = {1000, 2000, 3000};
        int minimum = 2000;
        int total = Arrays.stream(prices).filter(price -> price >= minimum).sum();
        System.out.println(total);
    }
}
